const fs = require('node:fs')
const path = require('node:path')

// One line per test-case hook, appended as it is called.
module.exports = class CallsReporter {
  constructor(globalConfig) {
    this.file = path.join(globalConfig.rootDir, 'calls.txt')
    fs.writeFileSync(this.file, '')
  }
  onTestCaseStart(test, info) {
    fs.appendFileSync(this.file, `start ${info.fullName}\n`)
  }
  onTestCaseResult(test, result) {
    fs.appendFileSync(this.file, `result ${result.fullName} ${result.status} invocations=${result.invocations} numPassingAsserts=${result.numPassingAsserts} failures=${result.failureMessages.length}\n`)
  }
}
